    [4107]={name="Tiger Hunter Gloves",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'Tiger Mastery'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Tiger Mastery",lore="Here is the final challenge that I will put forth. We've been tracking an elusive tiger for weeks."},
    [4109]={name="Excelsior Boots",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Excelsior'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Excelsior",lore="For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."},
    [4112]={name="Choker of the High Shaman",quality=2,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'Mok'thardin's Enchantment'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Mok'thardin's Enchantment",lore="There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring."},
    [4114]={name="Darktide Cape",quality=2,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'Keep An Eye Out'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Keep An Eye Out",lore="Avast! Who goes there? Argh, I am but useless without me special enchanted eye. Bad enough to have lost me eyes in battle in the first place!"},
    [4120]={name="Robe of Crystal Waters",quality=3,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'The Curse of the Tides'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="The Curse of the Tides",lore="So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for."},
    [4121]={name="Gemmed Gloves",quality=2,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Hostile Takeover'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Hostile Takeover",lore="He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!"},
    [4122]={name="Bookmaker's Scepter",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'The Hidden Key'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="The Hidden Key",lore="Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."},
    [4134]={name="Nimboya's Mystical Staff",quality=3,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'Saving Yenniku' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
