    [5016]={name="Artisan's Trousers",quality=2,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Jarl Needs a Blade'. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Jarl Needs a Blade",lore="I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."},
    [5181]={name="Vibrant Silk Cape",quality=2,ilvl=33,reqLevel=28,sourceType="world_drop",instructions="Drops from Singer (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Singer"},
    [5187]={name="Rhahk'Zor's Hammer",quality=3,ilvl=20,reqLevel=15,sourceType="boss_drop",instructions="Drops from Rhahk'Zor in The Deadmines.",zone="The Deadmines",npc="Rhahk'Zor"},
    [5195]={name="Gold-flecked Gloves",quality=3,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="Drops from Sneed (rare elite).",npc="Sneed"},
    [5274]={name="Rose Mantle",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Morganth'. In Redridge Mountains.",zone="Redridge Mountains",questName="Morganth",lore="After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."},
    [5275]={name="Binding Girdle",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Disruption Ends' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5310]={name="Sea Dog Britches",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Guns of Northwatch' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Guns of Northwatch",lore="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."},
    [5314]={name="Boar Hunter's Cape",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Consumed by Hatred' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Consumed by Hatred",lore="Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."},
    [5319]={name="Bashing Pauldrons",quality=1,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="Drops from Haren Swifthoof (rare elite) in The Loch.",zone="The Loch",npc="Haren Swifthoof"},
    [5324]={name="Engineer's Hammer",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5325]={name="Welding Shield",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5327]={name="Greasy Tinker's Pants",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Escape' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Escape",lore="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"},
    [5340]={name="Cauldron Stirrer",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Apothecary Zamah'. In The Barrens.",zone="The Barrens",questName="Apothecary Zamah",lore="I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'. In The Barrens.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5357]={name="Ward of the Vale",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Isha Awak' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Isha Awak",lore="The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."},
    [5404]={name="Serpent's Shoulders",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Lady Anacondra in Wailing Caverns.",zone="Wailing Caverns",npc="Lady Anacondra"},
