    [9518]={name="Mud's Crushers",quality=2,ilvl=36,sourceType="quest_reward",instructions="Reward from the quest 'Hungry!' - pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Hungry!",lore="Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you."},
    [9520]={name="Silent Hunter",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Call to Arms' - pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Call to Arms",lore="The head of the beast is ready to be taken off... with great force. You have shown every sign that you are able to help us with this final mighty blow."},
    [9639]={name="The Hand of Antu'sul",quality=3,ilvl=48,reqLevel=43,sourceType="boss_drop",instructions="Drops from Antu'sul in Zul'Farrak.",zone="Zul'Farrak",npc="Antu'sul",proc="Chance on hit: Blasts nearby enemies with thunder increasing the time between their attacks by 11% for 10 sec and doing 7 Nature damage to them.  Will affect up to 4 targets."},
    [9647]={name="Failed Flying Experiment",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Rescue OOX-22/FE!' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Rescue OOX-22/FE!",lore="The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."},
    [9650]={name="Honorguard Chestpiece",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Venom to the Undercity' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Venom to the Undercity",lore="The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."},
    [9651]={name="Gryphon Rider's Stormhammer",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",proc="Chance on hit: Blasts a target for 91 to 125 Nature damage."},
    [9652]={name="Gryphon Rider's Leggings",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"},
    [9658]={name="Boots of the Maharishi",quality=2,ilvl=43,sourceType="quest_reward",instructions="Reward from the quest 'Gordunni Cobalt' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Gordunni Cobalt",lore="I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"},
    [9663]={name="Dawnrider's Chestpiece",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Delivering the Relic' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Delivering the Relic",lore="If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."},
    [9683]={name="Strength of the Treant",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Spirit' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Weapons of Spirit",lore="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."},
