    [10637]={name="Brewer's Gloves",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10638]={name="Long Draping Cape",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10652]={name="Will of the Mountain Giant",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Spirit' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Weapons of Spirit",lore="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."},
    [10654]={name="Jutebraid Gloves",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'Horde Presence' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Horde Presence",lore="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."},
    [10659]={name="Shard of the Splithooves",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Heroes of Old'. In Blasted Lands.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
    [10727]={name="Goblin Dragon Gun",quality=1,ilvl=48,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",proc="Use: Deals 61 to 69 fire damage for 10 sec to all targets in a cone in front of the engineer using the weapon.   That is unless it explodes..... (5 Min Cooldown)"},
    [10742]={name="Dragonflight Leggings",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Set Them Ablaze!' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="Set Them Ablaze!",lore="Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."},
    [10748]={name="Wanderlust Boots",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Mazen's Behest' - pick it over the other choices. In Stormwind City.",zone="Stormwind City",questName="Mazen's Behest",lore="Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"},
    [10804]={name="Fist of the Damned",quality=3,ilvl=54,reqLevel=49,sourceType="boss_drop",instructions="Drops from Ogom the Wretched in Sunken Temple.",zone="Sunken Temple",npc="Ogom the Wretched",proc="Chance on hit: Steals 30 life from target enemy."},
    [10821]={name="Sower's Cloak",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Mura Runetotem' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
    [10838]={name="Might of Hakkar",quality=3,ilvl=54,reqLevel=49,sourceType="world_drop",instructions="Drops from Avatar of Hakkar (rare elite).",npc="Avatar of Hakkar"},
    [11469]={name="Bloodband Bracers",quality=2,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'The Captain's Chest'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="The Captain's Chest",lore="I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"},
