    [17182]={name="Sulfuras, Hand of Ragnaros",quality=5,ilvl=80,reqLevel=60,sourceType="special",instructions="Sulfuras, Hand of Ragnaros - Eye of Sulfuras (Ragnaros) + Sulfuron Hammer.",lore="Ragnaros wielded this hammer as the Firelord. Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer.",proc="Chance on hit: Hurls a fiery ball that causes 273 to 333 Fire damage and an additional 75 damage over 10 sec."},
