    [17903]={name="Stormpike Insignia Rank 5",quality=3,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Legendary Heroes'. In Alterac Valley.",zone="Alterac Valley",questName="Legendary Heroes",lore="Rise and be honored! Present your insignia.",proc="Use: Returns you to the sanctuary of Dun Baldar. (2 Min Cooldown)"},
    [17904]={name="Stormpike Insignia Rank 6",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'The Eye of Command'. In Alterac Valley.",zone="Alterac Valley",questName="The Eye of Command",lore="Your time has come again. You have earned a new ranking and as such, a new insignia denoting this rise in stature.",proc="Use: Returns you to the sanctuary of Dun Baldar."},
    [17908]={name="Frostwolf Insignia Rank 5",quality=3,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Legendary Heroes'. In Alterac Valley.",zone="Alterac Valley",questName="Legendary Heroes",lore="Your radiate command and power, shaman. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.",proc="Use: Returns you to the sanctuary of Frostwolf Keep. (2 Min Cooldown)"},
    [17909]={name="Frostwolf Insignia Rank 6",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'The Eye of Command'. In Alterac Valley.",zone="Alterac Valley",questName="The Eye of Command",lore="You have earned the Eye of Command. Present your insignia, Commander.",proc="Use: Returns you to the sanctuary of Frostwolf Keep."},
