    [18402]={name="Glowing Crystal Ring",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Uncovering Past Secrets' - pick it over the other choices. In Moonglade.",zone="Moonglade",questName="Uncovering Past Secrets",lore="Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you."},
