    [18814]={name="Choker of the Fire Lord",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [19024]={name="Arena Grand Master",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Arena Grandmaster'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Arena Grandmaster",lore="Avast Lubber! Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!",proc="Use: Absorbs 750 to 1250 damage.  Lasts 20 sec. (15 Min Cooldown)"},
