    [19829]={name="Zandalar Augur's Belt",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Augur's Belt'. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Augur's Belt",lore="Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"},
